package lk.sliit.nutricare.message;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.time.Instant;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1")public class MessageController{private final MessageRepository messages;private final NotificationRepository notifications;MessageController(MessageRepository m,NotificationRepository n){messages=m;notifications=n;}@PostMapping("/messages")@PreAuthorize("hasRole('DIETITIAN') or (hasRole('PATIENT') and principal == #r.senderId and principal == #r.patientId)")@ResponseStatus(HttpStatus.CREATED)SecureMessage send(@Valid@RequestBody MessageRequest r){return messages.save(new SecureMessage(r.senderId(),r.recipientId(),r.patientId(),r.body()));}@GetMapping("/messages/patient/{id}")@PreAuthorize("hasRole('DIETITIAN') or principal == #id")List<SecureMessage>conversation(@PathVariable UUID id){return messages.findByPatientIdOrderBySentAtAsc(id);}@PostMapping("/notifications")@PreAuthorize("hasAnyRole('DIETITIAN','DOCTOR','RECEPTION_STAFF','SYSTEM_ADMIN')")@ResponseStatus(HttpStatus.CREATED)Notification notify(@Valid@RequestBody NoticeRequest r){return notifications.save(new Notification(r.recipientId(),r.type(),r.channel(),r.message(),r.simulateFailure()?"FAILED":"DELIVERED_SIMULATED"));}@GetMapping("/notifications/recipient/{id}")@PreAuthorize("hasRole('SYSTEM_ADMIN') or principal == #id")List<Notification>notices(@PathVariable UUID id){return notifications.findByRecipientIdOrderByCreatedAtDesc(id);}@Scheduled(fixedDelay=60000)@Transactional public void retry(){notifications.findByStatusAndRetryAtBefore("FAILED",Instant.now()).forEach(Notification::retry);}record MessageRequest(@NotNull UUID senderId,@NotNull UUID recipientId,@NotNull UUID patientId,@NotBlank@Size(max=2000)String body){}record NoticeRequest(@NotNull UUID recipientId,@NotBlank String type,@Pattern(regexp="IN_APP|EMAIL|SMS")String channel,@NotBlank String message,boolean simulateFailure){}
}
